<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Drafts</title><style>
*{margin:0;padding:0;box-sizing:border-box}body{font-family:-apple-system,sans-serif;background:#f0ebe0;color:#4a3f35;height:100vh;overflow:hidden}
.page-container{display:flex;flex-direction:column;height:100vh}.toolbar{padding:10px 16px;background:#faf6ed;border-bottom:2px solid #d4c4a8}.toolbar-btn{background:#fff;border:1px solid #d4c4a8;padding:6px 12px;font-size:12px;cursor:pointer}.content-header{padding:12px 16px;background:#faf6ed;border-bottom:2px solid #d4c4a8}.content-title{font-size:16px;font-weight:600}.email-list-container{flex:1;overflow-y:auto}.email-list{list-style:none}.email-item{padding:12px 16px;border-bottom:1px solid #d4c4a8}.empty-state{padding:40px;text-align:center;color:#8a7a6a}</style></head>
<body><div class="page-container"><div class="toolbar"><button class="toolbar-btn" onclick="parent.loadEmails(true)">Refresh</button></div><div class="content-header"><h2 class="content-title">Drafts</h2></div><div class="email-list-container"><ul class="email-list" id="emailList"><li class="empty-state">Loading...</li></ul></div></div>
<script>const T='<?php echo $t; ?>';const F='drafts';let state={emails:[],page:1,hasMore:false,loading:false};function csrf(){return{'X-CSRF-TOKEN':T}}function esc(t){let d=document.createElement('div');d.textContent=t;return d.innerHTML}async function load(reset=true){if(state.loading)return;state.loading=true;try{let r=await fetch('../api/mail.php?action='+F+'&page='+state.page,{headers:csrf()});let d=await r.json();state.emails=d.emails||[];render()}catch(e){document.getElementById('emailList').innerHTML='<li class=empty-state>Error</li>'}state.loading=false}function render(){let L=document.getElementById('emailList');if(!state.emails.length){L.innerHTML='<li class=empty-state>No drafts</li>';return}L.innerHTML=state.emails.map(x=>'<li class=email-item onclick=parent.viewEmail('+x.id+',"'+F+'")><span style=flex:1>'+esc(x.subject||'(No subject)')+'</span></li>').join('')}load(true)</script></body></html>